served_sample_and_power": "520 matchups", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Calibration framework V4-V6; A5 vs A3 and A5b vs A5 signal in pts/100.", "observed_verdict": "null", "observed_failure_type": "B_powered_null", "observed_notes": "Model-scored, not observed outcomes.", "auto_confidence": "high (0.95)"}, "relationships": [{"rel": "auto_addresses_question", "node": "RQC:RQC-014"}]}, {"id": "FAM:SF-APPS-090", "label": "Study family SF-APPS-090: Connector diet x destination structural-gap match", "score": 0.722, "reached_via": ["FAM:SF19 auto_related_family (record_link_related_to) FAM:SF-APPS-090", "request matches RQC:RQC-046 (0.70); FAM:SF-APPS-090 auto_addresses_question RQC:RQC-046"], "attributes": {"observed_research_question": "Connector diet x destination structural-gap match", "auto_outcome_status": "untestable", "observed_hypothesis": "Diet-matching to a destination's thin initiation jobs predicts better post-move outcomes than mismatch.", "observed_result": "Binary match rate 15.7%. Taxonomy CONNECTOR delta match vs mis med +0.540 vs +0.069 p=0.156 n=5/14. Travel-check delta p=0.413. All-movers delta p=0.0283 (med +0.160 vs +0.053) but Spearman(match_score, delta)=-0.034 p=0 [cut; read_family for the full text]", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Connector subsets n=19/40; all-movers binary delta p=0.0283 does not replicate as a continuous Spearman and is not the licensed connector test.", "observed_sample_and_power": "n=19 taxonomy connectors; n=198 all movers", "observed_verdict": "null"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPS-086", "label": "Study family SF-APPS-086: Connector ecosystem quality: L(p) and |dA| do not predict Q_p", "score": 0.719, "reached_via": ["FAM:SF19 auto_related_family (record_link_related_to) FAM:SF-APPS-086", "request matches RQC:RQC-042 (0.69); FAM:SF-APPS-086 auto_addresses_question RQC:RQC-042"], "attributes": {"observed_research_question": "Connector ecosystem quality: L(p) and |dA| do not predict Q_p", "auto_outcome_status": "rejected", "observed_hypothesis": "Scalar structural load L(p) or an |dA|-weighted ecosystem lift predicts teammate-path quality Q_p.", "observed_result": "L(p) vs Q_p r~0. Uniform mean tm_dPPP vs Q_p r=+0.812; |dA|-weighted eco r=+0.703; eco residualized on uniform vs Q_p r=+0.084 p=0.399 NULL. Cosine to mean positive footprint vs Q_p r=-0.336 p=0.000559 (wrong sign). Pair [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Proposed structural metrics add nothing beyond a uniform average of teammate lifts (eco residual r=+0.084 p=0.399). Load is not quality.", "observed_sample_and_power": "n=102", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:DRIFT_NONSTATIONARITY"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-085"}]}, {"id": "FAM:SF-APPM-034", "label": "Study family SF-APPM-034: Counter identity selection at specific-action level (non-CUT)", "score": 0.454, "reached_via": ["request matches RQC:RQC-085 (0.72); FAM:SF-APPM-034 auto_addresses_question RQC:RQC-085"], "attributes": {"observed_research_question": "Counter identity selection at specific-action level (non-CUT)", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Choosing the specific counter identity (beyond tier) matters for non-CUT counters.", "observed_result": "Non-CUT gap +0.010, p=0.17 - not significant.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "+0.010, p=0.17.", "observed_sample_and_power": "NOT_RECORDED", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Non-CUT gap test (details not in file).", "observed_verdict": "null", "observed_failure_type": "E_unclear", "observed_notes": "NOT_RECORDED", "auto_confidence": "medium (0.65)", "observed_member_records": "APPM-034"}, "relationships": [{"rel": "auto_addresses_question", "node": "RQC:RQC-085"}, {"rel": "auto_uses_dataset", "node": "DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"}]}, {"id": "FAM:SF-APPA-045", "label": "Study family SF-APPA-045: Joint vs sequential Rank-then-Route ranking", "score": 0.438, "reached_via": ["request matches RQC:RQC-064 (0.69); FAM:SF-APPA-045 auto_addresses_question RQC:RQC-064"], "attributes": {"observed_research_question": "Joint vs sequential Rank-then-Route ranking", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Picking play type and player jointly beats sequential Rank then Route enough to justify the extra step.", "observed_result": "Joint pick = sequential 80.3%; joint reroutes 19.7% (547). Mean PPP left on table +0.020 all / +0.099 reroutes only (median +0.080). Play-type gap BEST vs 2nd 0.215 mean / 0.182 median. Routing premium +0.089. Strict dom [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Mean +0.020 PPP left on table is small; sequential declared safe ~80% with joint tiebreak in ~20%.", "observed_sample_and_power": "n=2,779 triggers", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "descriptive"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPS-087", "label": "Study family SF-APPS-087: Connector tangible impact: star shielding, TO, lineup lift", "score": 0.373, "reached_via": ["FAM:SF19 auto_related_family (record_link_related_to) FAM:SF-APPS-087"], "attributes": {"observed_research_question": "Connector tangible impact: star shielding, TO, lineup lift", "auto_outcome_status": "rejected", "observed_hypothesis": "Connector presence shields stars (higher TS, lower TO) and lifts lineup ORtg beyond talent.", "observed_result": "Star dTS +0.05 pp p=0.937; dTO +0.74 pp p=0.00364 (wrong sign for shielding). Star-init TO~HasConn beta=+0.34 pp p=0.439. HasConn on-off PPP BOTH_NULL (mean -0.041 p=0.939, median +0.528 p=0.731, n=73). Frequent-conn lin [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "PPP/TS/eFG shielding null; TO rate rises with connectors. Lineup ORtg lift is a talent confound (p=0.51 after TALENT; swap p=0.565).", "observed_verdict": "null"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:confounding"}, {"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:CONFOUNDING"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}, {"rel": "auto_related_family", "node": "FAM:SF-APPS-086"}]}], "n_results": 10}

